import collections
import hashlib
import json
import pathlib

directory = pathlib.Path('/home/liuxuedeng/Django-Agent/docs/refactor-evidence/20261011-root-pub-current-profile')

def key(frame):
    return (frame.get('functionName', ''), frame.get('url', ''), frame.get('lineNumber', -1), frame.get('columnNumber', -1))

def describe(frame):
    return {'function': frame[0], 'url': frame[1], 'line_1based': frame[2] + 1, 'column_1based': frame[3] + 1}

def summarize(path):
    data = json.loads(path.read_text())
    nodes = {node['id']: node for node in data['nodes']}
    parent = {child: node['id'] for node in data['nodes'] for child in node.get('children', [])}
    samples = data.get('samples', [])
    deltas = data.get('timeDeltas', [])
    assert len(samples) == len(deltas), 'Unpaired CPU sample and delta'
    paths = {}
    for node in nodes:
        chain = [node]
        while chain[-1] in parent:
            chain.append(parent[chain[-1]])
        paths[node] = chain
    self_time = collections.Counter()
    inclusive = collections.Counter()
    counts = collections.Counter()
    db_stacks = collections.Counter()
    observed = collections.Counter()
    subsets = {name: {'self': collections.Counter(), 'inclusive': collections.Counter(), 'weighted_us': 0}
        for name in ['publication_body', 'publication_outer_work', 'fts_batch_callback']}
    subset_keys = {
        'publication_body': ('', 'file:///home/liuxuedeng/Django-Agent/packages/core/src/documents/pipeline.ts', 0, 9206),
        'publication_outer_work': ('', 'file:///home/liuxuedeng/Django-Agent/packages/core/src/documents/pipeline.ts', 0, 8959),
        'fts_batch_callback': ('', 'file:///home/liuxuedeng/Django-Agent/packages/core/src/retrieval/search-index.ts', 11, 815),
    }
    timeline = data['startTime']
    first_last = {}
    for sample, delta in zip(samples, deltas):
        assert sample in nodes
        frame = key(nodes[sample]['callFrame'])
        self_time[frame] += delta
        counts[frame] += 1
        chain = paths[sample]
        unique = {key(nodes[node]['callFrame']) for node in chain}
        for ancestor in unique:
            inclusive[ancestor] += delta
        for name, marker in subset_keys.items():
            if marker in unique:
                subset = subsets[name]
                subset['weighted_us'] += delta
                subset['self'][frame] += delta
                for ancestor in unique:
                    subset['inclusive'][ancestor] += delta
        for marker in ['indexKeywords', '#rowid', 'insertMany', 'keyword', 'parseStoredJson', 'executePipeline']:
            if any(nodes[node]['callFrame'].get('functionName') == marker for node in chain):
                observed[marker] += delta
                entry = first_last.setdefault(marker, {'first_sample_offset_us': timeline - data['startTime'], 'last_sample_offset_us': 0})
                entry['last_sample_offset_us'] = timeline + delta - data['startTime']
        if frame[1].endswith('/storage/database.ts') and frame[0] in ['get', 'all', 'run']:
            stack = tuple(key(nodes[node]['callFrame']) for node in chain[:14])
            db_stacks[stack] += delta
        timeline += delta
    def ranked(counter, limit=40):
        return [{**describe(frame), 'sampled_ms': round(weight / 1000, 3), 'self_ms': round(self_time[frame] / 1000, 3),
            'inclusive_ms': round(inclusive[frame] / 1000, 3), 'self_samples': counts[frame]}
            for frame, weight in counter.most_common(limit)]
    business = [node for node in data['nodes'] if '/src/documents/pipeline.ts' in node['callFrame'].get('url', '')
        or '/test/document-workflow.test.ts' in node['callFrame'].get('url', '')]
    return {'file': path.name, 'sha256': hashlib.sha256(path.read_bytes()).hexdigest(),
        'start_time_us': data['startTime'], 'end_time_us': data['endTime'],
        'profile_elapsed_ms': round((data['endTime'] - data['startTime']) / 1000, 3),
        'paired_sample_count': len(samples), 'time_delta_sum_ms': round(sum(deltas) / 1000, 3),
        'unattributed_tail_ms': round((data['endTime'] - data['startTime'] - sum(deltas)) / 1000, 3),
        'min_delta_us': min(deltas), 'max_delta_us': max(deltas), 'negative_deltas': sum(delta < 0 for delta in deltas),
        'business_nodes': [{'node_id': node['id'], **describe(key(node['callFrame']))} for node in business],
        'self_top': ranked(self_time), 'inclusive_top': ranked(inclusive),
        'selected_inclusive_ms': {marker: round(weight / 1000, 3) for marker, weight in observed.items()},
        'selected_sample_spans': first_last,
        'selected_subsets': {name: {'marker': describe(subset_keys[name]),
            'sampled_ms': round(subset['weighted_us'] / 1000, 3),
            'self_top': [{**describe(frame), 'sampled_self_ms': round(weight / 1000, 3)}
                for frame, weight in subset['self'].most_common(24)]}
            for name, subset in subsets.items()},
        'database_self_by_stack': [{'sampled_self_ms': round(weight / 1000, 3),
            'stack_leaf_first': [describe(frame) for frame in stack]} for stack, weight in db_stacks.most_common(45)]}

profiles = [summarize(path) for path in sorted(directory.glob('*.cpuprofile'))]
initial_script_archive = directory / 'profile-analysis-sql-plan-first-fixture-script.json'
if not initial_script_archive.exists():
    initial_script = pathlib.Path('/tmp/marlin-current-publication-sql-plan-20261011.mjs')
    initial_script_archive.write_text(json.dumps({'path': str(initial_script),
        'sha256': hashlib.sha256(initial_script.read_bytes()).hexdigest(), 'content': initial_script.read_text()}, indent=2) + '\n')
report = {'method': {'unit': 'microseconds in raw profile converted to milliseconds',
    'self': 'sum timeDeltas for the sampled node, grouped by exact callFrame function/url/line/column',
    'inclusive': 'sum each sample timeDelta once for every distinct callFrame in that sample ancestry; recursive appearances deduplicated',
    'tail': 'endTime-startTime-sum(timeDeltas), not assigned to a function',
    'business_duration': 'stage wall-time from TAP; no monotonic stage timestamps exist to cut samples exactly at stage boundaries'},
    'command_receipt_sha256': hashlib.sha256((directory / 'command.json').read_bytes()).hexdigest(),
    'tap_sha256': hashlib.sha256((directory / 'large-local.tap').read_bytes()).hexdigest(),
    'profiles': profiles}
output = directory / 'profile-analysis.json'
output.write_text(json.dumps(report, ensure_ascii=False, indent=2) + '\n')
for profile in profiles:
    print(json.dumps({'file': profile['file'], 'elapsed': profile['profile_elapsed_ms'], 'delta_sum': profile['time_delta_sum_ms'],
        'samples': profile['paired_sample_count'], 'business_nodes': profile['business_nodes'][:12],
        'self_top': profile['self_top'][:8], 'selected': profile['selected_inclusive_ms'],
        'subsets': profile['selected_subsets'], 'min_delta_us': profile['min_delta_us'],
        'max_delta_us': profile['max_delta_us'], 'negative_deltas': profile['negative_deltas']}, ensure_ascii=False))

import assert from 'node:assert/strict';
import { createRequire } from 'node:module';
import { writeFile } from 'node:fs/promises';
import { dirname, join } from 'node:path';
const require = createRequire('/home/liuxuedeng/Django-Agent/packages/core/package.json');
const BetterSqlite3 = require('better-sqlite3');
const nativeBinding = join(dirname(require.resolve('better-sqlite3/package.json')), 'build', 'Release', 'better_sqlite3.node');
// Match the already verified core's explicit local native binding.
const db = new BetterSqlite3(':memory:', { nativeBinding });
try {
  db.defaultSafeIntegers();
  db.exec("CREATE VIRTUAL TABLE chunks_fts USING fts5(content, tokenize='trigram')");
  const maximum = 9223372036854775807n;
  const ids = Array.from({ length: 64 }, (_, i) => maximum - BigInt(i));
  const entries = ids.flatMap((id, i) => [id, 'newtoken预算😀 original source ' + i]);
  const deletion = `DELETE FROM chunks_fts WHERE rowid IN (${ids.map(() => '?').join(',')})`;
  const insertion = `INSERT INTO chunks_fts(rowid,content) VALUES ${ids.map(() => '(?,?)').join(',')}`;
  const replacement = insertion.replace('INSERT INTO', 'INSERT OR REPLACE INTO');
  const query = (sql, parameters) => ({ sql, binds: parameters.length,
    query_plan: db.prepare('EXPLAIN QUERY PLAN ' + sql).all(...parameters),
    vm: db.prepare('EXPLAIN ' + sql).all(...parameters) });
  const proof = { connection: ':memory:', production_connection_opened: false, native_binding: nativeBinding,
    better_sqlite3_version: require('better-sqlite3/package.json').version,
    sqlite_version: db.prepare('SELECT sqlite_version() AS version').get().version,
    fts_schema: db.prepare("SELECT sql FROM sqlite_master WHERE name='chunks_fts'").get().sql,
    statement_plans: [query(deletion, ids), query(insertion, entries), query(replacement, entries)] };
  db.prepare('INSERT INTO chunks_fts(rowid,content) VALUES(?,?),(?,?)').run(maximum, 'oldtoken预算😀', maximum - 1n, 'unrelatedtoken来源');
  db.prepare('INSERT OR REPLACE INTO chunks_fts(rowid,content) VALUES(?,?)').run(maximum, 'newtoken预算😀');
  assert.equal(db.prepare('SELECT rowid FROM chunks_fts WHERE chunks_fts MATCH ?').get('newtoken').rowid, maximum);
  assert.equal(db.prepare('SELECT count(*) AS n FROM chunks_fts WHERE chunks_fts MATCH ?').get('oldtoken').n, 0n);
  assert.equal(db.prepare('SELECT rowid FROM chunks_fts WHERE chunks_fts MATCH ?').get('unrelatedtoken').rowid, maximum - 1n);
  const stable = db.prepare('SELECT rowid,content FROM chunks_fts ORDER BY rowid').all();
  assert.throws(() => db.transaction(() => {
    db.prepare('INSERT OR REPLACE INTO chunks_fts(rowid,content) VALUES(?,?)').run(maximum, 'failedtoken预算😀');
    throw new Error('fixture rollback');
  })(), /fixture rollback/);
  assert.deepEqual(db.prepare('SELECT rowid,content FROM chunks_fts ORDER BY rowid').all(), stable);
  db.prepare('DELETE FROM chunks_fts WHERE rowid=?').run(maximum);
  assert.equal(db.prepare('SELECT rowid FROM chunks_fts WHERE rowid=?').get(maximum), undefined);
  proof.small_semantic_proof = { passed: true, maximum_rowid_exact: true, old_terms_removed: true,
    current_terms_searchable: true, unrelated_row_preserved: true, transaction_rollback: true,
    inactive_still_requires_explicit_deletion: true,
    business_scope_and_global_sequence_fence_tested_here: false, performance_speedup_tested_here: false };
  const output = '/home/liuxuedeng/Django-Agent/docs/refactor-evidence/20261011-root-pub-current-profile/profile-analysis-sql-plan.json';
  await writeFile(output, JSON.stringify(proof, (_key, value) => typeof value === 'bigint' ? value.toString() : value, 2) + '\n');
  console.log(JSON.stringify({ output, sqlite: proof.sqlite_version, schema: proof.fts_schema,
    plans: proof.statement_plans.map(({ sql, binds, query_plan, vm }) => ({ sql, binds, query_plan,
      virtual_opcodes: vm.filter(row => ['VFilter', 'VNext', 'VUpdate'].includes(row.opcode)) })), proof: proof.small_semantic_proof },
    (_key, value) => typeof value === 'bigint' ? value.toString() : value));
} finally { db.close(); }
